; per target ) to $7E00 so subsequent allocations
; clear the 256 - byte DL .APPMHI ( OS - tracked floor )
; gets the same value to keep CIO from growing into
; the heap .
LDA #$00
STA $86
LDA #$7E
STA $87
LDA #$00
STA $0E ; APPMHI lo
LDA #$7E
STA $0F ; APPMHI hi
