; pen branch .pen = 0 uses the inverted mask AND ' d in .
LDA _g8v_pen
BEQ _g8v_loop0
; pen = 1 : ORA mask into ( ptr ),Y each iter ; ptr+= 40 .
LDY #$00
_g8v_loop :
LDA _g8v_mask
ORA ( _g8v_ptr ),Y
STA ( _g8v_ptr ),Y
; ptr+= 40
CLC
LDA _g8v_ptr
ADC #$28
STA _g8v_ptr
BCC _g8v_lo_done
INC _g8v_ptr+1
_g8v_lo_done :
; 16 - bit countdown .Count starts at ( y1 - y0+1 )
; ( always >= 1 ) .Decrement cntLo ; on borrow,also
; decrement cntHi ; exit when both are zero .
LDA _g8v_cntLo
BNE _g8v_dec
LDA _g8v_cntHi
BEQ _g8v_done
DEC _g8v_cntHi
_g8v_dec :
DEC _g8v_cntLo
LDA _g8v_cntLo
ORA _g8v_cntHi
BNE _g8v_loop
JMP _g8v_done
_g8v_loop0 :
; pen = 0 : AND inverted mask into ( ptr ),Y .Stage the
; inverted mask once so each iter is just LDA mask ;
; AND ptr,Y ; STA ptr,Y ; advance .
LDA _g8v_mask
EOR #$FF
STA _g8v_mask
LDY #$00
_g8v_loop0_top :
LDA _g8v_mask
AND ( _g8v_ptr ),Y
STA ( _g8v_ptr ),Y
CLC
LDA _g8v_ptr
ADC #$28
STA _g8v_ptr
BCC _g8v_lo_done0
INC _g8v_ptr+1
_g8v_lo_done0 :
LDA _g8v_cntLo
BNE _g8v_dec0
LDA _g8v_cntHi
BEQ _g8v_done
DEC _g8v_cntHi
_g8v_dec0 :
DEC _g8v_cntLo
LDA _g8v_cntLo
ORA _g8v_cntHi
BNE _g8v_loop0_top
